1	"use client";
2	
3	import * as React from "react";
4	import { DataTable, type Column } from "@/components/ui/DataTable";
5	import { StatusBadge, type StatusTone } from "@/components/ui/StatusBadge";
6	import { formatCents } from "@/lib/format";
7	import { t } from "@/lib/i18n";
8	
9	export interface AdminSessionRow {
10	  id: string;
11	  dateLabel: string;
12	  dateMs: number;
13	  durationLabel: string;
14	  totalCents: number;
15	  commissionCents: number;
16	  earningsCents: number;
17	  status: string;
18	}
19	export interface AdminPaymentRow {
20	  id: string;
21	  dateLabel: string;
22	  dateMs: number;
23	  amountCents: number;
24	  status: string;
25	}
26	export interface AdminPayoutRow {
27	  id: string;
28	  periodLabel: string;
29	  periodMs: number;
30	  amountCents: number;
31	  status: string;
32	}
33	
34	const PAYMENT_TONE: Record<string, StatusTone> = {
35	  authorized: "neutral",
36	  captured: "success",
37	  refunded: "neutral",
38	  failed: "alert",
39	};
40	const SESSION_TONE: Record<string, StatusTone> = {
41	  completed: "success",
42	  in_progress: "info",
43	  cancelled: "neutral",
44	};
45	const PAYOUT_TONE: Record<string, StatusTone> = {
46	  paid: "success",
47	  scheduled: "warning",
48	};
49	
50	function Badge({ tone, label }: { tone: StatusTone; label: string }) {
51	  return <StatusBadge tone={tone}>{label}</StatusBadge>;
52	}
53	
54	export function AdminActivityTables({
55	  sessions,
56	  payments,
57	  payouts,
58	}: {
59	  sessions: AdminSessionRow[];
60	  payments: AdminPaymentRow[];
61	  payouts: AdminPayoutRow[];
62	}) {
63	  const sessionCols: Column<AdminSessionRow>[] = [
64	    { key: "dateLabel", header: t("admin.colDate"), sortable: true, sortValue: (r) => r.dateMs },
65	    { key: "durationLabel", header: t("provider.colDuration") },
66	    { key: "totalCents", header: t("admin.colAmount"), align: "right", sortable: true, sortValue: (r) => r.totalCents, render: (r) => formatCents(r.totalCents) },
67	    { key: "commissionCents", header: t("admin.colCommission"), align: "right", render: (r) => formatCents(r.commissionCents) },
68	    { key: "earningsCents", header: t("admin.colEarnings"), align: "right", render: (r) => formatCents(r.earningsCents) },
69	    { key: "status", header: t("admin.colStatus"), render: (r) => <Badge tone={SESSION_TONE[r.status] ?? "neutral"} label={r.status} /> },
70	  ];
71	  const paymentCols: Column<AdminPaymentRow>[] = [
72	    { key: "dateLabel", header: t("admin.colDate"), sortable: true, sortValue: (r) => r.dateMs },
73	    { key: "amountCents", header: t("admin.colAmount"), align: "right", sortable: true, sortValue: (r) => r.amountCents, render: (r) => formatCents(r.amountCents) },
74	    { key: "status", header: t("admin.colStatus"), render: (r) => <Badge tone={PAYMENT_TONE[r.status] ?? "neutral"} label={r.status} /> },
75	  ];
76	  const payoutCols: Column<AdminPayoutRow>[] = [
77	    { key: "periodLabel", header: t("provider.colPeriod"), sortable: true, sortValue: (r) => r.periodMs },
78	    { key: "amountCents", header: t("admin.colAmount"), align: "right", sortable: true, sortValue: (r) => r.amountCents, render: (r) => formatCents(r.amountCents) },
79	    { key: "status", header: t("admin.colStatus"), render: (r) => <Badge tone={PAYOUT_TONE[r.status] ?? "neutral"} label={r.status} /> },
80	  ];
81	
82	  return (
83	    <>
84	      <section className="flex flex-col gap-4">
85	        <h2 className="text-h2">{t("admin.sessionsHeading")}</h2>
86	        <DataTable caption={t("admin.sessionsCaption")} columns={sessionCols} rows={sessions} getRowKey={(r) => r.id} emptyText={t("admin.sessionsNone")} />
87	      </section>
88	      <section className="flex flex-col gap-4">
89	        <h2 className="text-h2">{t("admin.paymentsHeading")}</h2>
90	        <DataTable caption={t("admin.paymentsCaption")} columns={paymentCols} rows={payments} getRowKey={(r) => r.id} emptyText={t("admin.paymentsNone")} />
91	      </section>
92	      <section className="flex flex-col gap-4">
93	        <h2 className="text-h2">{t("admin.payoutsTableHeading")}</h2>
94	        <DataTable caption={t("admin.payoutsTableCaption")} columns={payoutCols} rows={payouts} getRowKey={(r) => r.id} emptyText={t("provider.payoutsNone")} />
95	      </section>
96	    </>
97	  );
98	}
